-- Applied to Lovable Supabase 2026-10-14; additive, idempotent, no customer data deletion.
BEGIN;
ALTER TABLE public.enquiries ADD COLUMN IF NOT EXISTS services text[] NOT NULL DEFAULT ARRAY['casino']::text[], ADD COLUMN IF NOT EXISTS trip_preferences jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS casino_name text, ADD COLUMN IF NOT EXISTS company_name text;
DO $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cb_enquiry_services_valid') THEN ALTER TABLE public.enquiries ADD CONSTRAINT cb_enquiry_services_valid CHECK(cardinality(services) BETWEEN 1 AND 6 AND services <@ ARRAY['casino','flight','hotel','transfer','cruise','package']::text[]); END IF;
IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cb_enquiry_preferences_valid') THEN ALTER TABLE public.enquiries ADD CONSTRAINT cb_enquiry_preferences_valid CHECK(jsonb_typeof(trip_preferences)='object' AND length(trip_preferences::text)<=10000); END IF;
IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cb_enquiry_company_valid') THEN ALTER TABLE public.enquiries ADD CONSTRAINT cb_enquiry_company_valid CHECK(company_name IS NULL OR length(company_name)<=160); END IF;
IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cb_enquiry_casino_name_valid') THEN ALTER TABLE public.enquiries ADD CONSTRAINT cb_enquiry_casino_name_valid CHECK(casino_name IS NULL OR length(casino_name)<=160); END IF;
END $$;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS phone text, ADD COLUMN IF NOT EXISTS residence text, ADD COLUMN IF NOT EXISTS customer_type text DEFAULT 'individual', ADD COLUMN IF NOT EXISTS company_name text;
REVOKE ALL ON TABLE public.profiles FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE(full_name,phone,residence,customer_type,company_name) ON public.profiles TO authenticated;
CREATE TABLE IF NOT EXISTS public.itinerary_segments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enquiry_id uuid NOT NULL REFERENCES public.enquiries(id) ON DELETE CASCADE,service_kind text NOT NULL CHECK(service_kind IN ('casino','flight','hotel','transfer','cruise','package')),summary text NOT NULL CHECK(char_length(summary) BETWEEN 1 AND 240),details jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(details)='object' AND length(details::text)<=10000),status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','reviewing','supplier_pending','proposed','arranged','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS cb_segments_enquiry_idx ON public.itinerary_segments(enquiry_id,created_at);
ALTER TABLE public.itinerary_segments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Segments visible to owner or admin" ON public.itinerary_segments;
CREATE POLICY "Segments visible to owner or admin" ON public.itinerary_segments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.enquiries e WHERE e.id=enquiry_id AND(e.user_id=(select auth.uid()) OR public.has_role((select auth.uid()),'admin'::public.app_role))));
DROP POLICY IF EXISTS "Admins manage itinerary segments" ON public.itinerary_segments;
CREATE POLICY "Admins manage itinerary segments" ON public.itinerary_segments FOR ALL TO authenticated USING(public.has_role((select auth.uid()),'admin'::public.app_role)) WITH CHECK(public.has_role((select auth.uid()),'admin'::public.app_role));
REVOKE ALL ON public.itinerary_segments FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.itinerary_segments TO authenticated;
CREATE TABLE IF NOT EXISTS public.crm_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enquiry_id uuid NOT NULL REFERENCES public.enquiries(id) ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES auth.users(id),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS cb_notes_enquiry_idx ON public.crm_notes(enquiry_id,created_at DESC);
ALTER TABLE public.crm_notes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin CRM notes only" ON public.crm_notes;
CREATE POLICY "Admin CRM notes only" ON public.crm_notes FOR ALL TO authenticated USING(public.has_role((select auth.uid()),'admin'::public.app_role)) WITH CHECK(public.has_role((select auth.uid()),'admin'::public.app_role) AND author_id=(select auth.uid()));
REVOKE ALL ON public.crm_notes FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON public.crm_notes TO authenticated;
CREATE TABLE IF NOT EXISTS public.crm_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enquiry_id uuid NOT NULL REFERENCES public.enquiries(id) ON DELETE CASCADE,title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 240),assigned_to uuid REFERENCES auth.users(id),due_date date,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','done','cancelled')),created_by uuid NOT NULL REFERENCES auth.users(id) DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS cb_tasks_enquiry_idx ON public.crm_tasks(enquiry_id,status);
ALTER TABLE public.crm_tasks ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin CRM tasks only" ON public.crm_tasks;
CREATE POLICY "Admin CRM tasks only" ON public.crm_tasks FOR ALL TO authenticated USING(public.has_role((select auth.uid()),'admin'::public.app_role)) WITH CHECK(public.has_role((select auth.uid()),'admin'::public.app_role));
REVOKE ALL ON public.crm_tasks FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.crm_tasks TO authenticated;
REVOKE ALL ON public.enquiries,public.user_roles,public.enquiry_status_events FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.enquiries,public.user_roles,public.enquiry_status_events TO authenticated;
GRANT INSERT ON public.enquiries TO authenticated;
GRANT UPDATE(status) ON public.enquiries TO authenticated;
COMMIT;